// reportAssets.js — the two WEG-EM Daily Status Report template images
// (the combined WEG + Electric Machinery header logo, and the four-color
// decorative bar) embedded directly as base64 data URIs.
//
// js/report.js used to fetch() these from icons/*.jpg at report-generation
// time. That works fine when the app is served over http(s), but fails
// silently (leaving a blank corner in the generated report) when the app is
// opened directly from disk as a file:// URL, since Chrome and most other
// browsers block fetch()/XHR reads of local files even from a file:// page,
// while still allowing normal <img>/<link> tag loading. Embedding the bytes
// here removes that dependency entirely — report generation now works the
// same way whether the app is hosted on a server or just double-clicked
// open from a folder.

const REPORT_LOGO_DATA_URL = 'data:image/jpeg;base64,';
const REPORT_COLOR_BAR_DATA_URL = 'data:image/jpeg;base64,';
